/* @lc app=leetcode id=3045 lang=kotlin */ class Solution { fun countPrefixSuffixPairs(words: Array<String>): Long = HashMap<Long, Int>().let { ch -> HashMap<Int, Int>().let { end -> words.fold(0L) { ans, w -> w.indices.fold(0 to 0L) { (node, a), i -> ch.getOrPut(node * 676L + (w[i] - 'a') * 26 + (w[w.length - 1 - i] - 'a')) { ch.size + 1 }.let { c -> c to a + (end[c] ?: 0) } }.let { (node, a) -> end.merge(node, 1) { x, y -> x + y }.let { ans + a } } } } } }